-- FarmGrid reference schema.
-- The authoritative schema is generated by SQLAlchemy in backend/app/models/models.py.
-- SQLite is the default demo database.

CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(160) UNIQUE NOT NULL, phone VARCHAR(30), password_hash VARCHAR(255) NOT NULL, role VARCHAR(40) NOT NULL DEFAULT 'farmer', is_active BOOLEAN DEFAULT 1, created_at DATETIME);
CREATE TABLE IF NOT EXISTS farms (id INTEGER PRIMARY KEY, farmer_id INTEGER NOT NULL, name VARCHAR(120) NOT NULL, location VARCHAR(200) NOT NULL, latitude FLOAT, longitude FLOAT, land_size_acres FLOAT NOT NULL, soil_type VARCHAR(80), soil_color VARCHAR(80), moisture FLOAT, water_availability FLOAT, previous_crop VARCHAR(100), previous_yield FLOAT, FOREIGN KEY(farmer_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS resources (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL, name VARCHAR(120) NOT NULL, resource_type VARCHAR(80) NOT NULL, specifications TEXT, location VARCHAR(200) NOT NULL, latitude FLOAT, longitude FLOAT, operating_from DATETIME NOT NULL, operating_until DATETIME NOT NULL, maintenance_status VARCHAR(30), status VARCHAR(30), FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS resource_requests (id INTEGER PRIMARY KEY, farmer_id INTEGER NOT NULL, farm_id INTEGER, resource_type VARCHAR(80) NOT NULL, requested_resource_id INTEGER, earliest_start DATETIME NOT NULL, latest_end DATETIME NOT NULL, duration_minutes INTEGER NOT NULL, crop VARCHAR(100) NOT NULL, crop_stage VARCHAR(100) NOT NULL, urgency_score INTEGER, weather_risk_score INTEGER, crop_readiness_score INTEGER, logistics_score INTEGER, resource_constraints_score INTEGER, waiting_score INTEGER, status VARCHAR(30), created_at DATETIME, FOREIGN KEY(farmer_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS bookings (id INTEGER PRIMARY KEY, request_id INTEGER UNIQUE NOT NULL, resource_id INTEGER NOT NULL, farmer_id INTEGER NOT NULL, start_time DATETIME NOT NULL, end_time DATETIME NOT NULL, buffer_minutes INTEGER, transit_minutes INTEGER, status VARCHAR(30), created_at DATETIME);
CREATE TABLE IF NOT EXISTS disruptions (id INTEGER PRIMARY KEY, resource_id INTEGER NOT NULL, reason VARCHAR(255) NOT NULL, start_time DATETIME NOT NULL, end_time DATETIME, active BOOLEAN, created_at DATETIME);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, title VARCHAR(160) NOT NULL, message TEXT NOT NULL, notification_type VARCHAR(60), is_read BOOLEAN, created_at DATETIME);
CREATE TABLE IF NOT EXISTS weather_records (id INTEGER PRIMARY KEY, location VARCHAR(200) NOT NULL, latitude FLOAT, longitude FLOAT, temperature FLOAT, humidity FLOAT, rainfall FLOAT, sunlight FLOAT, weather_condition VARCHAR(100), source VARCHAR(80), observed_at DATETIME);
CREATE TABLE IF NOT EXISTS labour_providers (id INTEGER PRIMARY KEY, user_id INTEGER, provider_type VARCHAR(30) NOT NULL, name VARCHAR(160) NOT NULL, region VARCHAR(160) NOT NULL, workers_available INTEGER, skills TEXT, daily_wage_per_worker FLOAT NOT NULL, available_from DATETIME, available_until DATETIME, is_active BOOLEAN);
CREATE TABLE IF NOT EXISTS labour_requests (id INTEGER PRIMARY KEY, farmer_id INTEGER NOT NULL, work_type VARCHAR(100) NOT NULL, workers_required INTEGER NOT NULL, start_date DATETIME NOT NULL, duration_days INTEGER NOT NULL, region VARCHAR(160) NOT NULL, urgency INTEGER, preferred_provider_type VARCHAR(30), status VARCHAR(30), created_at DATETIME);
CREATE TABLE IF NOT EXISTS labour_offers (id INTEGER PRIMARY KEY, labour_request_id INTEGER NOT NULL, provider_id INTEGER NOT NULL, offered_workers INTEGER NOT NULL, wage_per_worker_day FLOAT NOT NULL, status VARCHAR(30), created_at DATETIME);
CREATE TABLE IF NOT EXISTS market_orders (id INTEGER PRIMARY KEY, buyer_id INTEGER NOT NULL, crop VARCHAR(100) NOT NULL, quantity_kg FLOAT NOT NULL, quality_grade VARCHAR(30) NOT NULL, required_date DATETIME NOT NULL, location VARCHAR(200) NOT NULL, offered_price_per_kg FLOAT, status VARCHAR(30), created_at DATETIME);
CREATE TABLE IF NOT EXISTS yield_offers (id INTEGER PRIMARY KEY, market_order_id INTEGER NOT NULL, farmer_id INTEGER NOT NULL, quantity_kg FLOAT NOT NULL, action VARCHAR(20) NOT NULL, status VARCHAR(30), created_at DATETIME);
CREATE TABLE IF NOT EXISTS fertilizer_recommendations (id INTEGER PRIMARY KEY, farmer_id INTEGER, farm_id INTEGER, crop VARCHAR(100) NOT NULL, preferred_fertilizer VARCHAR(120), predicted_fertilizer VARCHAR(120), suitability_score FLOAT, model_used BOOLEAN, explanation TEXT, created_at DATETIME);
CREATE TABLE IF NOT EXISTS pesticide_recommendations (id INTEGER PRIMARY KEY, farmer_id INTEGER, farm_id INTEGER, crop VARCHAR(100) NOT NULL, pest VARCHAR(100) NOT NULL, predicted_pesticide VARCHAR(120), pest_pressure_score FLOAT, model_used BOOLEAN, explanation TEXT, created_at DATETIME);
CREATE TABLE IF NOT EXISTS offline_sync_items (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, client_id VARCHAR(120) UNIQUE NOT NULL, payload TEXT, status VARCHAR(30), created_at DATETIME);
